    for a in res['geocode_attrs']:
        res[a] = repr(getattr(mm, a))[:200]
    mmmenu = getattr(mm, 'mmqgis_menu', None)
    if mmmenu:
        def walk(m, prefix):
            out=[]
            for ac in m.actions():
                if ac.menu():
                    out += walk(ac.menu(), prefix+ac.text()+' > ')
                else:
                    out.append((prefix+ac.text(), ac.isEnabled(), ac.isVisible()))
            return out
        res['items'] = walk(mmmenu,'')
result = res"}
